// Radar Chart — Multivariate, route: jsx
// Source: original:gaps/radar
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from radar ----
// Attribute scores for three phone models, already normalized to 0-1 by the
// reviewer. Three series over six commensurate axes — deliberately at the
// documented ceiling for a readable radar, not beyond it.
const phoneScores: {
  axes: string[];
  series: { name: string; values: number[] }[];
} = {
  axes: ['Battery', 'Camera', 'Display', 'Performance', 'Durability', 'Value'],
  series: [
    { name: 'Aurora X', values: [0.62, 0.94, 0.9, 0.88, 0.55, 0.48] },
    { name: 'Pulse 9', values: [0.85, 0.7, 0.72, 0.66, 0.8, 0.9] },
    { name: 'Terra S', values: [0.75, 0.55, 0.6, 0.5, 0.92, 0.78] }
  ]
};

const LABEL_PAD = 16;
const LEGEND_ROW = 18;
const RING_LEVELS = [1 / 3, 2 / 3, 1];

/**
 * Axis names plus one value per axis per series, aligned by index and already
 * normalized to 0-1 by the caller — the chart maps 0-1 to the radius and applies
 * no scaling of its own. Documented for few, commensurate series (about three).
 */
export type Data = {
  axes: string[];
  series: { name: string; values: number[] }[];
};

export default function RadarChart({ data = phoneScores, width }: { data?: Data; width: number }) {
  const radius = Math.max(1, Math.min(width, 560) / 2 - 64);
  const cx = width / 2;
  const cy = radius + 36;
  const legendHeight = data.series.length * LEGEND_ROW;
  const height = Math.round(cy + radius + 32 + legendHeight + 8);

  const r = useMemo(() => d3.scaleLinear().domain([0, 1]).range([0, radius]), [radius]);

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.series.map((s) => s.name))
        .range(d3.schemeObservable10),
    [data]
  );

  const { spokes, polygons } = useMemo(() => {
    const n = data.axes.length;
    const angle = (i: number) => (i / n) * 2 * Math.PI - Math.PI / 2;
    const spokes = data.axes.map((name, i) => {
      const a = angle(i);
      return {
        name,
        cos: Math.cos(a),
        sin: Math.sin(a),
        x: Math.cos(a) * radius,
        y: Math.sin(a) * radius,
        labelX: Math.cos(a) * (radius + LABEL_PAD),
        labelY: Math.sin(a) * (radius + LABEL_PAD)
      };
    });
    const polygons = data.series.map((s) => ({
      name: s.name,
      points: s.values.map((v, i) => ({
        x: Math.cos(angle(i)) * r(v),
        y: Math.sin(angle(i)) * r(v)
      }))
    }));
    return { spokes, polygons };
  }, [data, radius, r]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Radar chart comparing three phone models as overlaid polygons across six normalized attribute axes, with grid rings and a legend"
    >
      <g transform={`translate(${cx},${cy})`}>
        {RING_LEVELS.map((level) => (
          <circle key={level} r={r(level)} fill="none" stroke="var(--line)" />
        ))}
        {spokes.map((s) => (
          <g key={s.name}>
            <line x1={0} y1={0} x2={s.x} y2={s.y} stroke="var(--line)" />
            <text
              x={s.labelX}
              y={s.labelY}
              fontSize={11}
              fill="var(--text)"
              textAnchor={Math.abs(s.cos) < 0.1 ? 'middle' : s.cos > 0 ? 'start' : 'end'}
              dy={s.sin < -0.5 ? '0em' : s.sin > 0.5 ? '0.7em' : '0.32em'}
            >
              {s.name}
            </text>
          </g>
        ))}
        {polygons.map((p) => (
          <g key={p.name}>
            <polygon
              points={p.points.map((pt) => `${pt.x},${pt.y}`).join(' ')}
              fill={color(p.name)}
              fillOpacity={0.12}
              stroke={color(p.name)}
              strokeWidth={1.5}
            />
            {p.points.map((pt, i) => (
              <circle key={i} cx={pt.x} cy={pt.y} r={2.5} fill={color(p.name)} />
            ))}
          </g>
        ))}
      </g>
      <g transform={`translate(${Math.max(8, cx - radius - 56)},${cy + radius + 32})`}>
        {data.series.map((s, i) => (
          <g key={s.name} transform={`translate(0,${i * LEGEND_ROW})`}>
            <rect width={11} height={11} rx={1.5} fill={color(s.name)} />
            <text x={16} y={9} fontSize={11} fill="var(--text)">
              {s.name}
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
